package com.tastenest.servlet;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*; import com.tastenest.util.DB;
@WebServlet("/order")
public class OrderServlet extends HttpServlet {
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException{res.setContentType("application/json");try{DB.init();String name=req.getParameter("name"),mobile=req.getParameter("mobile"),address=req.getParameter("address"),payment=req.getParameter("payment"),items=req.getParameter("items");double total=Double.parseDouble(req.getParameter("total"));int uid;try(Connection c=DB.get()){c.setAutoCommit(false);Object sessionUser=req.getSession().getAttribute("userId"); if(sessionUser!=null){uid=(Integer)sessionUser;} else {try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,mobile,email,password) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,mobile);p.setString(3,mobile+"@demo.tastenest");p.setString(4,"demo");p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){k.next();uid=k.getInt(1);}} req.getSession().setAttribute("userId",uid);req.getSession().setAttribute("userName",name);}
 PreparedStatement op=c.prepareStatement("INSERT INTO orders(user_id,total_amount,address,payment_method) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS);op.setInt(1,uid);op.setDouble(2,total);op.setString(3,address);op.setString(4,payment);op.executeUpdate();ResultSet kr=op.getGeneratedKeys();kr.next();int oid=kr.getInt(1);for(String part:items.split(";")){if(part.isBlank())continue;String[] a=part.split(",");PreparedStatement ip=c.prepareStatement("INSERT INTO order_items(order_id,menu_item_id,quantity,price) VALUES(?,?,?,?)");ip.setInt(1,oid);ip.setInt(2,Integer.parseInt(a[0]));ip.setInt(3,Integer.parseInt(a[1]));ip.setDouble(4,Double.parseDouble(a[2]));ip.executeUpdate();}c.commit();res.getWriter().print("{\"ok\":true,\"orderId\":"+oid+"}");}}catch(Exception e){res.setStatus(500);res.getWriter().print("{\"ok\":false,\"error\":\""+e.getMessage().replace("\"","'")+"\"}");}}
}
